// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Private_Bank} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Private_Bank c;

    function setUp() public {
        c = new Private_Bank(address(this));
    }

    function _test(uint256 _amount) internal {
        _amount = bound(_amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(_amount > 0 && _amount <= c.MinDeposit());
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        bool reverted;
        uint balAfter;
        try c.Deposit{value: _amount}() {
            balAfter = c.balances(address(this));
            reverted = false;
        } catch {
            balAfter = c.balances(address(this));
            reverted = true;
        }
        assertTrue(reverted || balAfter == balBefore);
    }

    function testFuzz_test(uint256 _amount) public {
        _test(_amount);
    }

    receive() external payable {}
}
